public class Robot extends RootstockRobot { }  // ctor auto-configures Logger: metadata (git SHA via GVersion), WPILOGWriter("/U/logs")+NT4Publisher in REAL, WPILOGReader(LogFileUtil.findReplayLog()) in REPLAY, Hoot sidecar in SIM.

@RootstockIO  // re-export of @AutoLog, plus generated no-op + sim implementations
public class ElevatorIOInputs { public double positionMeters; public double velocityMps; public double appliedVolts; public double[] currentAmps; public boolean connected; }

// Compile-time enforcement AdvantageKit lacks:
@ReplayUnsafe   // annotation the Gradle plugin scans for; build fails if HAL/Timer/Math.random is called outside an IO impl

RobotState.log("Superstructure/State", state);   // typed, unit-aware (2026 unit metadata)

PoseEngine pose = PoseEngine.builder()
  .kinematics(kinematics).driveBaseRadius(Meters.of(0.41))
  .odometry(drive::sampleOdometry)        // 250 Hz thread samples, timestamped
  .gyro(pigeon).backupGyro(navx)          // 6328 dual-gyro fallback
  .camera(Limelight.megaTag2("ll-front"))
  .camera(Photon.multiTag("pv-back", ROBOT_TO_BACK))
  .arbiter(CameraArbiter.bestByTagAreaAndCount())      // 2910 pattern
  .stdDev(StdDevModels.distanceScaled(0.4, 0.05))      // sigmaXY = base * d^2 / tagCount
  .reject(Rejections.gyroRateAbove(DegreesPerSecond.of(720)))   // Limelight doc rule
  .reject(Rejections.noTags(), Rejections.offField(Meters.of(0.5)), Rejections.zAbove(Meters.of(0.25)))
  .rotationTrust(RotationTrust.GYRO_ONLY)   // enforces the (.7,.7,9999999) intent structurally
  .tiltScaling(true)
  .skid(SkidDetector.moduleVelocityDispersion(0.15))  // downweight odometry, don't drop it
  .build();

// Characterization + measurement, both one command:
Command wheelRadius = Characterize.wheelRadius(drive);
// prints: measuredRadius = gyroDelta * driveBaseRadius / wheelDelta  (6328's formula)
Command ff = Characterize.driveFeedforward(drive);   // 0.1 V/s ramp, least-squares kS/kV
OdometryReport r = OdometryReport.squareTest(drive, Meters.of(3.0)).run();
// r.closureErrorMeters(), r.headingDriftDegrees(), r.suggestedWheelRadius(), r.visionDisagreementRms()

Command align = AutoAlign.to(() -> targetPose)
    .translation(4.0, 8.0)                       // maxVel m/s, maxAccel m/s^2
    .rotation(DegreesPerSecond.of(540), DegreesPerSecondPerSecond.of(720))
    .ffRamp(Meters.of(0.05), Meters.of(0.60))    // 6328 linearFFMin/MaxRadius
    .tolerance(Meters.of(0.02), Degrees.of(1.5))
    .omegaOverride(() -> Optional.empty())
    .driverNudge(driver::getLeftY, driver::getLeftX, 0.25)  // partial authority, never zero
    .build();
Trigger settled = align.withinTolerance(Meters.of(0.02), Rotation2d.fromDegrees(1.5));
// All gains as RootstockTunable so they hot-reload without a redeploy (LoggedTunableNumber equivalent)

// Constants.mode ∈ {REAL, SIM, REPLAY} drives IO selection automatically:
Elevator elevator = new Elevator(RootstockIO.select(ElevatorIOTalonFX::new,
                                                  () -> ElevatorIOSim.of(DCMotor.getKrakenX60(2), gearing, Kilograms.of(6), Inches.of(2))));

SimWorld world = SimWorld.forGame(Game.REBUILT_2026)
   .robot(SimRobot.swerve(driveConfig, Kilograms.of(55), Inches.of(30)))
   .intake(IntakeSim.overBumper(Inches.of(26)))
   .launcher(ShotSim.projectile(launchCalculator::solve))
   .opponents(3)
   .build();

// Headless CI match:  ./gradlew simulateJava -Prootstock.headlessMatch=autos/3piece
MatchResult res = HeadlessMatch.run(world, autos.get("3piece"), Seconds.of(15));
assertThat(res.piecesScored()).isAtLeast(3);
assertThat(res.finalPoseError()).isLessThan(Meters.of(0.10));

AutoLibrary autos = AutoLibrary.builder()
   .drive(drive, pose)                     // supplies pose/reset/chassisSpeeds/output
   .choreo()                               // -> ChoreoLib AutoFactory + AutoRoutine
   .pathplanner(ppRobotConfig)             // -> AutoBuilder.configure(...)
   .actions(scoreL4, intakeGround, climb)  // auto-registered as NamedCommands AND choreo markers
   .flipForAlliance(true)
   .build();

AutoSpec three = autos.routine("3piece")
   .leg("Start_to_A").resetOdometryAtStart()
   .atMarker("prep", sup.goalCommand(L4))
   .onDone(scoreL4)
   .leg("A_to_Source").whileActive(intakeGround)
   .build();
autoChooser.addOption("3 piece", three.command());

// Optional advanced module (6328 'salesman'): order the scoring targets optimally
List<Pose2d> order = RouteOptimizer.tsp(startPose, candidateTargets, TimeCostModel.fromTransitionCosts(sup));

TunableMechanism elev = Tunable.elevator("Elevator")
   .plant(DCMotor.getKrakenX60(2), gearing, Kilograms.of(6.0), Inches.of(2.0))
   .io(elevator::setVoltage, elevator::getPositionMeters, elevator::getVelocityMps)
   .limits(Meters.of(0.0), Meters.of(1.60))
   .lesson(Lesson.POSITION_WITH_MOTION_PROFILE);
RootstockTuner.register(elev);

// On the robot, from the tuner UI (NT-backed web page or AdvantageScope-adjacent app):
//   Step 1 "Find kS": ramps voltage, asks the student to mark where it starts moving
//   Step 2 "Find kV/kA": quasistatic + dynamic SysId routines, auto least-squares fit
//   Step 3 "Add kP": shows profile setpoint vs measured overlay, suggests kP, student bisects
//   Step 4 "Check": scores overshoot / settling / steady-state error, explains WHY in plain text

RootstockTuner.gains("Elevator").kP();      // reads /home/lvuser/rootstock/gains.json, hot-reloadable
RootstockTuner.exportReport(Path.of("tuning-report.md"));   // student-authored evidence of what was tuned

ShotSolver solver = ShotSolver.builder()
   .target(() -> FieldConstants.HUB_CENTER)
   .launcherOffset(new Transform2d(0.15, 0.0, Rotation2d.kZero))   // off-center launcher correction
   .map("hood",     InterpolatingDoubleTreeMap.ofPairs(1.12, 0.95, 5.01, 0.42))
   .map("flywheel", flywheelMap).map("kicker", kickerMap)
   .timeOfFlight(tofMap)
   .dragConstant(0.60)
   .phaseDelay(Seconds.of(0.030))
   .iterations(20)
   .build();

ShotSolution s = solver.solve(pose.get(), pose.getFieldVelocity());
s.valid(); s.driveAngle(); s.driveAngularVelocity();
s.param("hood"); s.paramVelocity("hood");     // feed as FF to the hood controller
s.timeOfFlight();

// Verification loop nobody else packages (1678 'verification'/'trends'):
ShotLog.record(s, () -> hubCounter.detectedScore());   // logs predicted vs observed, running hit rate

public abstract class RootstockRobotConfig {
  public abstract double wheelRadiusMeters();
  public abstract Translation2d[] moduleTranslations();
  public abstract Map<String, Transform3d> cameraTransforms();
  public abstract Map<String, Gains> defaultGains();
  public boolean hasElevator() { return true; }      // capability flags gate subsystem construction
}
public enum RobotType { COMP, PRACTICE, LEGACY_2025, SIMBOT }
Constants.ROBOT = RobotType.COMP;   // single edit point; getMode() returns REAL/SIM/REPLAY

// Subsystems are constructed conditionally, so a missing mechanism does not crash the robot:
Optional<Elevator> elevator = Subsystems.ifPresent(config::hasElevator, () -> new Elevator(io));

// Emitted automatically by ScoringAction / AutoAlign / Superstructure:
//   /Rootstock/Events  ->  {t, type: CYCLE_START|ALIGN_START|ALIGN_DONE|RELEASE|ABORT, target, poseError}

CycleReport rep = CycleStats.fromLog(Path.of("logs/2026-xyz-q34.wpilog"));
rep.cycleCount(); rep.medianCycleSeconds(); rep.p90CycleSeconds();
rep.medianAlignSeconds(); rep.abortRate(); rep.visionUptimeFraction();
rep.slowestTransition();     // e.g. STOW->L4 took 1.42 s vs 1.10 s measured baseline
rep.writeMarkdown(Path.of("reports/q34.md"));

// CLI for the whole event:
//   rootstock stats logs/ --event 2026xyz  ->  trend of median cycle time per match

class ScoreL4Test {
  @RegisterExtension RootstockTest t = RootstockTest.headless();   // resets CommandScheduler, HAL, SimHooks, DriverStationSim

  @Test void elevatorRoutesThroughGatewayWhenGoingStowToL4() {
    sup.setGoal(L4);
    t.stepSeconds(2.0);                     // advances SimHooks + CommandScheduler.run() at 50 Hz
    assertThat(t.visitedStates()).containsExactly(STOW, CLEAR_CROSSBEAM, INTERMEDIATE_L4, L4).inOrder();
  }

  @Test void interlockBlocksL1WhileHoldingAlgae() {
    gripper.setHasAlgae(true);
    assertThat(sup.pathTo(L1)).isEmpty();
  }

  @Test void replayOfCompetitionLogProducesSameOutputs() {
    ReplayAssert.of("logs/2026-q34.wpilog").expectOutputsUnchanged();  // regression-locks a real match
  }
}

